// User-selected defaults from the three supplied Oyun Kuralları screenshots.
// Legacy speed/impulse values use one 50 ms simulation step, independent of render FPS.
export const RULES=Object.freeze({mapWidth:32000,mapHeight:32000,roundSeconds:3600,startSeconds:0,noDecaySeconds:3,spawnMass:100,maxCells:25,maxCellMass:220000,speed:48,speedExponent:0.2222222222,decay:0.006,decayMin:100,splitMin:36,splitSpeed:3.75,launchSteps:32,launchDamping:0.85,mergeSeconds:15,mergeMassSeconds:0.02,ejectMin:32,ejectMass:12,ejectCost:16,ejectSpeed:160,foodCount:450,foodMass:10,virusCount:75,virusMax:1000,virusMass:250,virusFeeds:5,virusGain:1});
export const PHYSICS_STEP=.05;
export const movementSpeed=mass=>RULES.speed/Math.pow(Math.max(1,mass),RULES.speedExponent)/PHYSICS_STEP;
export const mergeDelay=mass=>(RULES.mergeSeconds+mass*RULES.mergeMassSeconds)*1000;
export const RULE_GROUPS=[['Dünya',[['Harita genişliği','mapWidth'],['Harita yüksekliği','mapHeight'],['Tur süresi · sn','roundSeconds'],['Başlangıç sayacı · sn','startSeconds'],['Son saniyeler erime yok · sn','noDecaySeconds']]],['Oyuncu',[['Doğuş kütlesi','spawnMass'],['En çok parça','maxCells'],['Parça başına en çok kütle','maxCellMass'],['Hız','speed'],['Hız kütle üssü','speedExponent'],['Saniyelik erime','decay'],['Erime alt sınırı','decayMin']]],['Bölünme / birleşme',[['Bölünme alt sınırı','splitMin'],['Bölünme hızı','splitSpeed'],['Fırlama adımı','launchSteps'],['Fırlama sönümü','launchDamping'],['Birleşme (taban) · sn','mergeSeconds'],['Birleşme (kütle başına) · sn','mergeMassSeconds']]],['Yem / diken',[['W için en az kütle','ejectMin'],['Atılan yem','ejectMass'],['Hücreden düşen','ejectCost'],['Yem hızı','ejectSpeed'],['Yem sayısı','foodCount'],['Yem kütlesi','foodMass'],['Diken sayısı','virusCount'],['Diken üst sınırı','virusMax'],['Diken kütlesi','virusMass'],['Diken beslenme sayısı','virusFeeds'],['Dikenden kütle (1 = alır)','virusGain']]]];
